     */
    private User findKerberosUser() {
      if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
        KerberosPrincipal kp = getCanonicalUser(KerberosPrincipal.class);
        if (LOG.isDebugEnabled()) {
          LOG.debug("using kerberos user:" + kp);
        }
        return kp != null ? new User(kp.getName()) : null;
      }
      return null;
    }

    /**
