    private User findEnvUser() {
      if (!isSecurityEnabled() && (getCanonicalUser(KerberosPrincipal.class) == null)) {
        String envUser = System.getenv(HADOOP_USER_NAME);
        if (envUser == null) {
          envUser = System.getProperty(HADOOP_USER_NAME);
        }
        if (envUser != null) {
          if (LOG.isDebugEnabled()) {
            LOG.debug("using env user:" + envUser);
          }
          return new User(envUser);
        }
      }
      return null;
    }

    /**
     * Attempt to find a local OS user principal.
     */
    private User findLocalUser() {
      User localUser = getCanonicalUser(OS_PRINCIPAL_CLASS);
      if (localUser != null) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("using local user:" + localUser);
        }
      }
      return localUser;
    }

    /**
     * Add the given User principal to the subject.
     */
    private void addUserToSubject(User user) throws LoginException {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Using user: \"" + user + "\" with name " + user.getName());
      }

      User userEntry;
      try {
        userEntry = new User(user.getName());
      } catch (Exception e) {
        throw (LoginException)(new LoginException(e.toString()).initCause(e));
      }
      if (LOG.isDebugEnabled()) {
        LOG.debug("User entry: \"" + userEntry.toString() + "\"");
      }

      subject.getPrincipals().add(userEntry);
    }

