  /** 
   * UgiMetrics maintains UGI activity statistics
   * and publishes them through the metrics interfaces.
   */
  @Metrics(about="User and group related metrics", context="ugi")
  static class UgiMetrics {
    final MetricsRegistry registry = new MetricsRegistry("UgiMetrics");

    @Metric("Rate of successful kerberos logins and latency (milliseconds)")
    MutableRate loginSuccess;
    @Metric("Rate of failed kerberos logins and latency (milliseconds)")
    MutableRate loginFailure;
    @Metric("GetGroups") MutableRate getGroups;
    MutableQuantiles[] getGroupsQuantiles;

    static UgiMetrics create() {
      return DefaultMetricsSystem.instance().register(new UgiMetrics());
    }

    void addGetGroups(long latency) {
      getGroups.add(latency);
      if (getGroupsQuantiles != null) {
        for (MutableQuantiles q : getGroupsQuantiles) {
          q.add(latency);
        }
      }
    }
  }

  /**
   * A login module that looks at the Kerberos, Unix, or Windows principal and
   * adds the corresponding UserName.
   */
  @InterfaceAudience.Private
  public static class HadoopLoginModule implements LoginModule {
    private Subject subject;

    @Override
    public boolean abort() throws LoginException {
      return true;
    }

    private <T extends Principal> T getCanonicalUser(Class<T> cls) {
      for(T user: subject.getPrincipals(cls)) {
        return user;
      }
      return null;
    }

    @Override
    public boolean commit() throws LoginException {
      logDebug("hadoop login commit");
      if (hasExistingUser()) {
        logDebug("using existing subject:" + subject.getPrincipals());
        return true;
      }
      Principal user = getKerberosUser();
      if (user == null) {
        user = getEnvUser();
      }
      if (user == null) {
        user = getOsUser();
      }
      if (user != null) {
        logDebug("Using user: \"" + user + "\" with name " + user.getName());
        addUserToSubject(user);
        return true;
      }
      LOG.error("Can't find user in " + subject);
      throw new LoginException("Can't find user name");
    }

    private boolean hasExistingUser() {
      return !subject.getPrincipals(User.class).isEmpty();
    }

    private Principal getKerberosUser() {
      if (isAuthenticationMethodEnabled(AuthenticationMethod.KERBEROS)) {
        Principal p = getCanonicalUser(KerberosPrincipal.class);
        logDebug("using kerberos user:" + p);
        return p;
      }
      return null;
    }

    private Principal getEnvUser() {
      if (!isSecurityEnabled() && (getKerberosUser() == null)) {
        String envUser = System.getenv(HADOOP_USER_NAME);
        if (envUser == null) {
          envUser = System.getProperty(HADOOP_USER_NAME);
        }
        return envUser == null ? null : new User(envUser);
      }
      return null;
    }

    private Principal getOsUser() {
      Principal p = getCanonicalUser(OS_PRINCIPAL_CLASS);
      logDebug("using local user:" + p);
      return p;
    }

    private void addUserToSubject(Principal user) throws LoginException {
      try {
        User userEntry = new User(user.getName());
        subject.getPrincipals().add(userEntry);
      } catch (Exception e) {
        throw (LoginException)(new LoginException(e.toString()).initCause(e));
      }
    }

    private void logDebug(String msg) {
      if (LOG.isDebugEnabled()) {
        LOG.debug(msg);
      }
    }

    @Override
    public void initialize(Subject subject, CallbackHandler callbackHandler,
                           Map<String, ?> sharedState, Map<String, ?> options) {
      this.subject = subject;
    }

    @Override
    public boolean login() throws LoginException {
      if (LOG.isDebugEnabled()) {
        LOG.debug("hadoop login");
      }
      return true;
    }

    @Override
    public boolean logout() throws LoginException {
      if (LOG.isDebugEnabled()) {
        LOG.debug("hadoop logout");
      }
      return true;
    }
  }

