private static void parseEntityFields(TimelineEntity entity, LeveldbIterator iterator,
      byte[] prefix, int prefixlen, EnumSet<Field> fields) throws IOException {
    boolean events = fields.contains(Field.EVENTS);
    boolean lastEvent = fields.contains(Field.LAST_EVENT_ONLY);
    boolean relatedEntities = fields.contains(Field.RELATED_ENTITIES);
    boolean primaryFilters = fields.contains(Field.PRIMARY_FILTERS);
    boolean otherInfo = fields.contains(Field.OTHER_INFO);
    for (; iterator.hasNext(); iterator.next()) {
      byte[] key = iterator.peekNext().getKey();
      if (!prefixMatches(prefix, prefixlen, key)) {
        break;
      }
      if (key.length == prefixlen) {
        continue;
      }
      byte col = key[prefixlen];
      if (col == PRIMARY_FILTERS_COLUMN[0] && primaryFilters) {
        addPrimaryFilter(entity, key, prefixlen + PRIMARY_FILTERS_COLUMN.length);
      } else if (col == OTHER_INFO_COLUMN[0] && otherInfo) {
        entity.addOtherInfo(parseRemainingKey(key, prefixlen + OTHER_INFO_COLUMN.length),
            GenericObjectMapper.read(iterator.peekNext().getValue()));
      } else if (col == RELATED_ENTITIES_COLUMN[0] && relatedEntities) {
        addRelatedEntity(entity, key, prefixlen + RELATED_ENTITIES_COLUMN.length);
      } else if (col == EVENTS_COLUMN[0] && (events || (lastEvent && entity.getEvents().size() == 0))) {
        TimelineEvent event = getEntityEvent(null, key, prefixlen + EVENTS_COLUMN.length,
            iterator.peekNext().getValue());
        if (event != null) {
          entity.addEvent(event);
        }
      } else if (col == DOMAIN_ID_COLUMN[0]) {
        String domainId = new String(iterator.peekNext().getValue(), Charset.forName("UTF-8"));
        entity.setDomainId(domainId);
      } else if (col != INVISIBLE_REVERSE_RELATED_ENTITIES_COLUMN[0]) {
        LOG.warn(String.format("Found unexpected column for entity %s of type %s (0x%02x)",
            entity.getEntityId(), entity.getEntityType(), col));
      }
    }
  }
