  /**
   * Subqueue metrics might be a little out of date because fair shares are
   * recalculated at the update interval, but the root queue metrics needs to
   * be updated synchronously with allocations and completions so that cluster
   * metrics will be consistent.
   */
  private void updateRootQueueMetrics() {
    rootMetrics.setAvailableResourcesToQueue(
        Resources.subtract(
            clusterResource, rootMetrics.getAllocatedResources()));
  }

  /**
   * Check if preemption is enabled and the utilization threshold for
   * preemption is met.
   *
   * @return true if preemption should be attempted, false otherwise.
   */
  private boolean shouldAttemptPreemption() {
    if (preemptionEnabled) {
      return (preemptionUtilizationThreshold < Math.max(
          (float) rootMetrics.getAllocatedMB() / clusterResource.getMemory(),
          (float) rootMetrics.getAllocatedVirtualCores() /
              clusterResource.getVirtualCores()));
    }
    return false;
  }

  @Override
  public QueueMetrics getRootQueueMetrics() {
    return rootMetrics;
  }

  /**
   * Event handler strategy interface.
   */
  private interface EventHandler {
    void handle(SchedulerEvent event);
  }

  /**
   * Map of event types to handlers.
   */
  private static final Map<SchedulerEventType, EventHandler> EVENT_HANDLERS =
      new HashMap<SchedulerEventType, EventHandler>();

  static {
    EVENT_HANDLERS.put(SchedulerEventType.NODE_ADDED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            NodeAddedSchedulerEvent nodeAddedEvent =
                (NodeAddedSchedulerEvent) event;
            addNode(nodeAddedEvent.getAddedRMNode());
            recoverContainersOnNode(nodeAddedEvent.getContainerReports(),
                nodeAddedEvent.getAddedRMNode());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.NODE_REMOVED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            NodeRemovedSchedulerEvent nodeRemovedEvent =
                (NodeRemovedSchedulerEvent) event;
            removeNode(nodeRemovedEvent.getRemovedRMNode());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.NODE_UPDATE,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            NodeUpdateSchedulerEvent nodeUpdatedEvent =
                (NodeUpdateSchedulerEvent) event;
            nodeUpdate(nodeUpdatedEvent.getRMNode());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.APP_ADDED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            AppAddedSchedulerEvent appAddedEvent =
                (AppAddedSchedulerEvent) event;
            String queueName =
                resolveReservationQueueName(appAddedEvent.getQueue(),
                    appAddedEvent.getApplicationId(),
                    appAddedEvent.getReservationID());
            if (queueName != null) {
              addApplication(appAddedEvent.getApplicationId(),
                  queueName, appAddedEvent.getUser(),
                  appAddedEvent.getIsAppRecovering());
            }
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.APP_REMOVED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            AppRemovedSchedulerEvent appRemovedEvent =
                (AppRemovedSchedulerEvent) event;
            removeApplication(appRemovedEvent.getApplicationID(),
                appRemovedEvent.getFinalState());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.NODE_RESOURCE_UPDATE,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            NodeResourceUpdateSchedulerEvent nodeResourceUpdatedEvent =
                (NodeResourceUpdateSchedulerEvent) event;
            updateNodeResource(nodeResourceUpdatedEvent.getRMNode(),
                nodeResourceUpdatedEvent.getResourceOption());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.APP_ATTEMPT_ADDED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            AppAttemptAddedSchedulerEvent appAttemptAddedEvent =
                (AppAttemptAddedSchedulerEvent) event;
            addApplicationAttempt(appAttemptAddedEvent.getApplicationAttemptId(),
                appAttemptAddedEvent.getTransferStateFromPreviousAttempt(),
                appAttemptAddedEvent.getIsAttemptRecovering());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.APP_ATTEMPT_REMOVED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            AppAttemptRemovedSchedulerEvent appAttemptRemovedEvent =
                (AppAttemptRemovedSchedulerEvent) event;
            removeApplicationAttempt(
                appAttemptRemovedEvent.getApplicationAttemptID(),
                appAttemptRemovedEvent.getFinalAttemptState(),
                appAttemptRemovedEvent.getKeepContainersAcrossAppAttempts());
          }
        });
    EVENT_HANDLERS.put(SchedulerEventType.CONTAINER_EXPIRED,
        new EventHandler() {
          @Override
          public void handle(SchedulerEvent event) {
            ContainerExpiredSchedulerEvent containerExpiredEvent =
                (ContainerExpiredSchedulerEvent) event;
            ContainerId containerId = containerExpiredEvent.getContainerId();
            completedContainer(getRMContainer(containerId),
                SchedulerUtils.createAbnormalContainerStatus(
                    containerId,
                    SchedulerUtils.EXPIRED_CONTAINER),
                RMContainerEventType.EXPIRE);
          }
        });
  }

  @Override
  public void handle(SchedulerEvent event) {
    EventHandler handler = EVENT_HANDLERS.get(event.getType());
    if (handler != null) {
      handler.handle(event);
    } else {
      LOG.error("Unknown event arrived at FairScheduler: " + event.toString());
    }
  }

  private synchronized String resolveReservationQueueName(String queueName,
      ApplicationId applicationId, ReservationId reservationID) {
    FSQueue queue = queueMgr.getQueue(queueName);
    if ((queue == null) || !allocConf.isReservable(queue.getQueueName())) {
      return queueName;
    }
    // Use fully specified name from now on (including root. prefix)
    queueName = queue.getQueueName();
    if (reservationID != null) {
      String resQName = queueName + "." + reservationID.toString();
      queue = queueMgr.getQueue(resQName);
      if (queue == null) {
        String message =
            "Application "
                + applicationId
                + " submitted to a reservation which is not yet currently active: "
                + resQName;
        this.rmContext.getDispatcher().getEventHandler()
            .handle(new RMAppRejectedEvent(applicationId, message));
        return null;
      }
      if (!queue.getParent().getQueueName().equals(queueName)) {
        String message =
            "Application: " + applicationId + " submitted to a reservation "
                + resQName + " which does not belong to the specified queue: "
                + queueName;
        this.rmContext.getDispatcher().getEventHandler()
            .handle(new RMAppRejectedEvent(applicationId, message));
        return null;
      }
      // use the reservation queue to run the app
      queueName = resQName;
    } else {
      // use the default child queue of the plan for unreserved apps
      queueName = getDefaultQueueForPlanQueue(queueName);
    }
    return queueName;
  }

  private String getDefaultQueueForPlanQueue(String queueName) {
    String planName = queueName.substring(queueName.lastIndexOf(".") + 1);
    queueName = queueName + "." + planName + ReservationConstants.DEFAULT_QUEUE_SUFFIX;
    return queueName;
  }

