  Map<ApplicationAttemptId, FiCaSchedulerApp> applicationAttemptMap =
      new HashMap<ApplicationAttemptId, FiCaSchedulerApp>();

  Set<FiCaSchedulerApp> pendingApplications;

  private float minimumAllocationFactor;

