  // Helper methods to build the state machine factory
  private static StateMachineFactory<JobImpl, JobStateInternal, JobEventType, JobEvent>
      buildStateMachineFactory() {
    StateMachineFactory<JobImpl, JobStateInternal, JobEventType, JobEvent> factory =
        new StateMachineFactory<JobImpl, JobStateInternal, JobEventType, JobEvent>(JobStateInternal.NEW);
    addTransitionsFromNewState(factory);
    addTransitionsFromInitedState(factory);
    addTransitionsFromSetupState(factory);
    addTransitionsFromRunningState(factory);
    addTransitionsFromKillWaitState(factory);
    addTransitionsFromCommittingState(factory);
    addTransitionsFromSucceededState(factory);
    addTransitionsFromFailWaitState(factory);
    addTransitionsFromFailAbortState(factory);
    addTransitionsFromKillAbortState(factory);
    addTransitionsFromFailedState(factory);
    addTransitionsFromKilledState(factory);
    addTransitionsFromErrorState(factory);
    addTransitionsFromRebootState(factory);
    factory.installTopology();
    return factory;
  }

  private static void addTransitionsFromNewState(
      StateMachineFactory<JobImpl, JobStateInternal, JobEventType, JobEvent> factory) {
    factory.addTransition(JobStateInternal.NEW, JobStateInternal.NEW,
        JobEventType.JOB_DIAGNOSTIC_UPDATE,
        DIAGNOSTIC_UPDATE_TRANSITION)
        .addTransition(JobStateInternal.NEW, JobStateInternal.NEW,
        JobEventType.JOB_COUNTER_UPDATE, COUNTER_UPDATE_TRANSITION)
        .addTransition(JobStateInternal.NEW,
            EnumSet.of(JobStateInternal.INITED, JobStateInternal.NEW),
            JobEventType.JOB_INIT,
            new InitTransition())
        .addTransition(JobStateInternal.NEW, JobStateInternal.FAIL_ABORT,
            JobEventType.JOB_INIT_FAILED,
            new InitFailedTransition())
        .addTransition(JobStateInternal.NEW, JobStateInternal.KILLED,
            JobEventType.JOB_KILL,
            new KillNewJobTransition())
        .addTransition(JobStateInternal.NEW, JobStateInternal.ERROR,
            JobEventType.INTERNAL_ERROR,
            INTERNAL_ERROR_TRANSITION)
        .addTransition(JobStateInternal.NEW, JobStateInternal.REBOOT,
            JobEventType.JOB_AM_REBOOT,
            INTERNAL_REBOOT_TRANSITION)
        .addTransition(JobStateInternal.NEW, JobStateInternal.NEW,
            JobEventType.JOB_UPDATED_NODES);
  }

  private static void addTransitionsFromInitedState(
