  /**
   * Given datanode address or host name, returns the DatanodeDescriptor for the
   * same, or if it doesn't find the datanode, it looks for a machine local and
   * then rack local datanode, if a rack local datanode is not possible either,
   * it returns the DatanodeDescriptor of any random node in the cluster.
   *
   * @param address hostaddress:transfer address
   * @return the best match for the given datanode
   */
  DatanodeDescriptor getDatanodeDescriptor(String address) {
    DatanodeID dnId = parseDNFromHostsEntry(address);
    String host = dnId.getIpAddr();
    int xferPort = dnId.getXferPort();
    DatanodeDescriptor node = getDatanodeByXferAddr(host, xferPort);
    if (node == null) {
      node = getDatanodeByHost(host);
    }
    if (node == null) {
      node = findBestMatch(dnId, host);
    }
    return node;
  }

  /**
   * Find the best matching datanode descriptor when a direct lookup fails.
   * This method encapsulates the fallback logic to machine local, rack local,
   * or any random node in the cluster.
   *
   * @param dnId the parsed DatanodeID from the address
   * @param host the IP address of the datanode
   * @return a suitable DatanodeDescriptor or null if none found
   */
  private DatanodeDescriptor findBestMatch(DatanodeID dnId, String host) {
    String networkLocation = resolveNetworkLocationWithFallBackToDefaultLocation(dnId);
    List<Node> rackNodes = getNetworkTopology()
        .getDatanodesInRack(networkLocation);
    if (rackNodes != null) {
      DatanodeDescriptor node = findMachineLocal(rackNodes, host);
      if (node != null) {
        return node;
      }
      if (!rackNodes.isEmpty()) {
        return (DatanodeDescriptor) rackNodes
            .get(DFSUtil.getRandom().nextInt(rackNodes.size()));
      }
    }
    return (DatanodeDescriptor) getNetworkTopology()
        .chooseRandom(NodeBase.ROOT);
  }

  /**
   * Search for a machine local datanode within the given rack nodes.
   *
   * @param rackNodes list of nodes in the rack
   * @param host IP address to match
   * @return the matching DatanodeDescriptor or null if not found
   */
  private DatanodeDescriptor findMachineLocal(List<Node> rackNodes, String host) {
    for (Node rackNode : rackNodes) {
      if (((DatanodeDescriptor) rackNode).getIpAddr().equals(host)) {
        return (DatanodeDescriptor) rackNode;
      }
    }
    return null;
  }

